/** Lenses added to a shelf after the bag's order was fixed: they go at the end (as in the game). */
private val addedLater = listOf("Ohi Kor 28mm f/2.8 · Whacked", "Itabashi Takuma 55mm f/1.8 · Whacked", "Itabashi Takuma 85mm f/1.8 · Whacked", "Itabashi Takuma 135mm f/3.5 · Whacked", "Burnside Pinhole Cap 32mm f/128")

/** Every lens, in the game's bag order (a lens's index is its number). */
val lensBag: List<Lens> by lazy {
    val all = lensCollections.flatMap { it.lenses }
    all.filter { it.name !in addedLater } + addedLater.mapNotNull { n -> all.firstOrNull { it.name == n } }
}
